<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class AccountLedgerController extends Controller {
 private function school(){ $u=auth()->user();abort_unless($u->status && $u->school_id,403);return $u->school_id; }
 private function accounts(){return DB::table('account_ledger_accounts')->where('school_id',$this->school());}
 private function journals(){return DB::table('account_journals')->where('school_id',$this->school());}
 private function lines(){return DB::table('account_journal_lines as l')->join('account_journals as j','j.id','=','l.journal_id')->join('account_ledger_accounts as a','a.id','=','l.account_id')->where('j.school_id',$this->school())->where('a.school_id',$this->school());}
 public function index(){ $accounts=$this->accounts()->orderBy('code')->get();$totals=$this->lines()->where('j.status','posted')->groupBy('l.account_id')->selectRaw('l.account_id,SUM(l.debit) debit,SUM(l.credit) credit')->get()->keyBy('account_id');$entries=$this->journals()->orderByDesc('id')->paginate(20);$details=$this->lines()->whereIn('j.id',$entries->pluck('id'))->select('l.*','a.name')->get()->groupBy('journal_id');return view('accounts.ledger-index',compact('accounts','totals','entries','details')); }
 public function account(Request $r){$v=$r->validate(['code'=>['required','string','max:30',Rule::unique('account_ledger_accounts')->where('school_id',$this->school())],'name'=>'required|string|max:150','type'=>'required|in:cash,bank,asset,liability,equity,income,expense']);DB::table('account_ledger_accounts')->insert($v+['school_id'=>$this->school(),'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Account created.');}
 public function store(Request $r){$v=$r->validate(['entry_date'=>'required|date_format:Y-m-d|before_or_equal:today','kind'=>'required|in:journal,contra,opening,receipt,payment','description'=>'required|string|max:255','lines'=>'required|array|min:2|max:20','lines.*.account_id'=>['required','distinct',Rule::exists('account_ledger_accounts','id')->where('school_id',$this->school())],'lines.*.debit'=>'required|numeric|decimal:0,2|min:0|max:9999999999.99','lines.*.credit'=>'required|numeric|decimal:0,2|min:0|max:9999999999.99']);$d=0;$c=0;$cashD=0;$cashC=0;$types=$this->accounts()->pluck('type','id');foreach($v['lines'] as $l){$x=(int)round($l['debit']*100);$y=(int)round($l['credit']*100);abort_unless(($x>0 xor $y>0),422,'Each line must have exactly one positive side.');$d+=$x;$c+=$y;$liquid=in_array($types[$l['account_id']],['cash','bank']);if($liquid){$cashD+=$x;$cashC+=$y;}if($v['kind']==='contra')abort_unless($liquid,422,'Contra requires cash or bank accounts.');}abort_unless($d===$c && $d>0,422,'Debit and credit must balance.');if($v['kind']==='receipt')abort_unless($cashD===$d && $cashC===0,422,'Receipt must debit cash or bank.');if($v['kind']==='payment')abort_unless($cashC===$c && $cashD===0,422,'Payment must credit cash or bank.');DB::transaction(function()use($v){$id=DB::table('account_journals')->insertGetId(['school_id'=>$this->school(),'entry_date'=>$v['entry_date'],'kind'=>$v['kind'],'description'=>$v['description'],'created_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);foreach($v['lines'] as $l)DB::table('account_journal_lines')->insert(['journal_id'=>$id,'account_id'=>$l['account_id'],'debit'=>$l['debit'],'credit'=>$l['credit']]);});return back()->with('success','Journal submitted for approval.');}
 public function review(Request $r,$id){$v=$r->validate(['decision'=>'required|in:posted,rejected']);DB::transaction(function()use($v,$id){$j=$this->journals()->where('id',$id)->lockForUpdate()->first();abort_unless($j,404);abort_unless($j->status==='pending' && $j->created_by!=auth()->id(),422,'A different authorized user must review a pending entry.');$this->journals()->where('id',$id)->update(['status'=>$v['decision'],'reviewed_by'=>auth()->id(),'reviewed_at'=>now(),'updated_at'=>now()]);});return back()->with('success','Review saved.');}
 public function book(Request $r,$id){$a=$this->accounts()->where('id',$id)->first();abort_unless($a,404);$v=$r->validate(['from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d']);$from=$v['from']??now()->startOfMonth()->toDateString();$to=$v['to']??now()->toDateString();abort_if($from>$to,422);$q=$this->lines()->where('l.account_id',$id)->where('j.status','posted');$opening=(clone $q)->where('j.entry_date','<',$from)->selectRaw('COALESCE(SUM(l.debit-l.credit),0) balance')->first()->balance;$rows=(clone $q)->whereBetween('j.entry_date',[$from,$to])->select('l.*','j.entry_date','j.description','j.kind')->orderBy('j.entry_date')->orderBy('j.id')->get();return view('accounts.ledger-book',compact('a','from','to','opening','rows'));}
}
